if(!isset($_SESSION['user'])||$_SESSION['user']['role']!=='admin'){header('Location: ../login.php');exit;}
$studentId=(int)($_GET['student_id']??0);$term=trim($_GET['term']??'');
if($_SERVER['REQUEST_METHOD']==='POST'){ verifyCsrf();$studentId=(int)($_POST['student_id']??0);$term=trim($_POST['term']??'');
 if(isset($_POST['set_status'])&&$studentId&&$term){$status=in_array($_POST['set_status'],['draft','published','locked'],true)?$_POST['set_status']:'draft';$q=$pdo->prepare('INSERT INTO result_status(student_id,term,status,published_at,locked_at) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),published_at=VALUES(published_at),locked_at=VALUES(locked_at)');$now=date('Y-m-d H:i:s');$q->execute([$studentId,$term,$status,in_array($status,['published','locked'],true)?$now:null,$status==='locked'?$now:null]);}
}
$students=$pdo->query('SELECT st.id,u.name,st.roll_no,p.level,p.name program_name,st.semester_or_year FROM students st JOIN users u ON u.id=st.user_id JOIN programs p ON p.id=st.program_id ORDER BY u.name')->fetchAll();
$selected=null;$result=null;$overall=null;$terms=[];
if($studentId){$q=$pdo->prepare('SELECT st.*,u.name,u.email,p.level,p.name program_name,p.specialization FROM students st JOIN users u ON u.id=st.user_id JOIN programs p ON p.id=st.program_id WHERE st.id=?');$q->execute([$studentId]);$selected=$q->fetch();if($selected){$terms=academicTerms($selected['level']);$term=$term?:$selected['semester_or_year'];$result=studentResult($pdo,$studentId,$term);$overall=studentOverall($pdo,$studentId);$status=resultStatus($pdo,$studentId,$term);}}
$pageTitle='Results & GPA';require '../includes/header.php';?>
<div class="container py-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="fw-bold">Results & GPA</h2><p class="text-muted mb-0">Term-wise result, GPA and printable DMC.</p></div><a href="../admin.php" class="btn btn-outline-secondary">Admin Dashboard</a></div>
<div class="card shadow-sm border-0 mb-4"><div class="card-body"><form method="post" class="row g-2 align-items-end"><?php echo csrfField(); ?><div class="col-md-6"><label class="form-label">Select Student</label><select name="student_id" id="studentSelect" class="form-select" required onchange="this.form.submit()"><option value="">Select student</option><?php foreach($students as $s):?><option value="<?=$s['id']?>" <?=$studentId==$s['id']?'selected':''?>><?=htmlspecialchars($s['roll_no'].' — '.$s['name'].' — '.$s['program_name'].' — '.$s['semester_or_year'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Term</label><select name="term" class="form-select"><option value="">Student Current Term</option><?php foreach($terms as $t):?><option value="<?=htmlspecialchars($t)?>" <?=$term===$t?'selected':''?>><?=htmlspecialchars($t)?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-primary w-100">View Result</button></div></form></div></div>
<?php if($selected&&$result):?><div class="card shadow-sm border-0"><div class="card-body"><div class="d-flex justify-content-between"><div><h4 class="fw-bold mb-1"><?=htmlspecialchars($selected['name'])?></h4><div class="text-muted"><?=htmlspecialchars($selected['roll_no'].' · '.$selected['program_name'].' · '.($term?:$selected['semester_or_year']))?></div></div><div class="text-end"><div class="small text-muted">Term GPA</div><div class="display-6 fw-bold"><?=number_format($result['gpa'],2)?></div></div></div><div class="table-responsive mt-4"><table class="table align-middle"><thead><tr><th>Code</th><th>Subject</th><th>Credit Hours</th><th>Marks %</th><th>Grade</th><th>Grade Point</th></tr></thead><tbody><?php foreach($result['rows'] as $r):?><tr><td><?=htmlspecialchars($r['code'])?></td><td><?=htmlspecialchars($r['name'])?></td><td><?=number_format($r['credit_hours'],1)?></td><td><?=number_format($r['percent'],2)?>%</td><td><span class="badge text-bg-<?=($r['letter_grade']==='F'?'danger':'success')?>"><?=htmlspecialchars($r['letter_grade'])?></span></td><td><?=number_format($r['grade_point'],2)?></td></tr><?php endforeach;?></tbody></table></div><div class="alert alert-light border"><strong>Status:</strong> <?=htmlspecialchars(strtoupper($status))?> &nbsp; <strong>Term Credits:</strong> <?=number_format($result['credits'],1)?> &nbsp; <strong>Term Quality Points:</strong> <?=number_format($result['quality'],2)?> &nbsp; <strong>Term GPA:</strong> <?=number_format($result['gpa'],2)?> &nbsp; <strong>Overall GPA:</strong> <?=number_format($overall['gpa'],2)?></div><div class="d-flex gap-2 flex-wrap"><a class="btn btn-primary" target="_blank" href="../result_card.php?student_id=<?=$studentId?>&term=<?=urlencode($term)?>">Print Result Card / DMC</a><form method="post" class="d-flex gap-2"><?php echo csrfField(); ?><input type="hidden" name="student_id" value="<?=$studentId?>"><input type="hidden" name="term" value="<?=htmlspecialchars($term)?>"><button name="set_status" value="published" class="btn btn-success">Publish</button><button name="set_status" value="locked" class="btn btn-danger">Lock Result</button><button name="set_status" value="draft" class="btn btn-outline-secondary">Reopen / Draft</button></form></div></div></div><?php elseif($studentId):?><div class="alert alert-warning">Student not found.</div><?php endif;?></div><?php require '../includes/footer.php';?>
